const visited = new WeakSet()
const obj1 = { page: "home" }
const obj2 = { page: "about" }
visited.add(obj1)
visited.add(obj2)
return {
  hasObj1: visited.has(obj1),
  hasObj2: visited.has(obj2),
  hasObj3: visited.has({ page: "home" })
}
